import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.BiXHgXAn.js";const c=JSON.parse('{"title":"Taskfile Versions","description":"How to use the Taskfile schema version to ensure users are using the correct versions of Task","frontmatter":{"title":"Taskfile Versions","description":"How to use the Taskfile schema version to ensure users are using the correct versions of Task","section":"Project","docType":"project","outline":"deep"},"headers":[],"relativePath":"docs/taskfile-versions.md","filePath":"next/docs/taskfile-versions.md"}'),n={name:"docs/taskfile-versions.md"};function o(r,s,l,h,p,d){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="taskfile-versions" tabindex="-1">Taskfile Versions <a class="header-anchor" href="#taskfile-versions" aria-label="Permalink to &quot;Taskfile Versions&quot;">​</a></h1><p>The Taskfile schema slowly changes as new features are added and old ones are removed. This document explains how to use a Taskfile&#39;s schema version to ensure that the users of your Taskfile are using the correct versions of Task.</p><h2 id="what-the-taskfile-version-means" tabindex="-1">What the Taskfile version means <a class="header-anchor" href="#what-the-taskfile-version-means" aria-label="Permalink to &quot;What the Taskfile version means&quot;">​</a></h2><p>The schema version at the top of every Taskfile corresponds to a version of the Task CLI, and by extension, the features that are provided by that version. When creating a Taskfile, you should specify the <em>minimum</em> version of Task that supports the features you require. If you try to run a Taskfile with a version of Task that does not meet this minimum required version, it will exit with an error. For example, given a Taskfile that starts with:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3.2.1&#39;</span></span></code></pre></div><p>When executed with Task <code>v3.2.0</code>, it will exit with an error. Running with version <code>v3.2.1</code> or higher will work as expected.</p><p>Task accepts any <a href="https://semver.org/" target="_blank" rel="noreferrer">SemVer</a> compatible string including versions which omit the minor or patch numbers. For example, <code>3</code>, <code>3.0</code>, and <code>3.0.0</code> all mean the same thing and are all valid. Most Taskfiles only specify the major version number. However it can be useful to be more specific when you intend to share a Taskfile with others.</p><p>For example, the Taskfile below makes use of aliases:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  hello</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    aliases</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hi</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hey</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">echo &quot;Hello, world!&quot;</span></span></code></pre></div><p>Aliases were introduced in Task <code>v3.17.0</code>, but the Taskfile only specifies <code>3</code> as the version. This means that a user who has <code>v3.16.0</code> or lower installed will get a potentially confusing error message when trying to run the Task as the Taskfile specifies that any version greater or equal to <code>v3.0.0</code> is fine.</p><p>Instead, we should start the file like this:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3.17&#39;</span></span></code></pre></div><p>Now when someone tries to run the Taskfile with an older version of Task, they will receive an error prompting them to upgrade their version of Task to <code>v3.17.0</code> or greater.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Note that this functionality was introduced in <a href="https://github.com/go-task/task/releases/tag/v3.34.0" target="_blank" rel="noreferrer">v3.34.0</a>, so older versions are not able to give you this warning.</p></div><h2 id="versions-1-2" tabindex="-1">Versions 1 &amp; 2 <a class="header-anchor" href="#versions-1-2" aria-label="Permalink to &quot;Versions 1 &amp; 2&quot;">​</a></h2><p>Version 1 and 2 of Task are no longer officially supported and anyone still using them is strongly encouraged to upgrade to the latest version of Task.</p><p>While <code>version: 2</code> of Task did support schema versions, the behavior did not work in quite the same way and cannot be relied upon for the purposes discussed above.</p>`,17)])])}const u=e(n,[["render",o]]);export{c as __pageData,u as default};
